using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Management;using System.Collections.Generic;using System.Web.Script.Serialization;using System.Security.Cryptography;using Microsoft.Win32;
namespace LaunchDesk.Development.RemoteProjectLab.Guest
{
class GuestRmsIdentity {
 const string Root=@"C:\AVEVA\AVEVA Licensing System";
 static string Hash(string p){try{using(var f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","");}catch(IOException){return "unavailable: file locked; no changes attempted";}}
 static object Query(string q,string[] fields){var rows=new List<object>();using(var search=new ManagementObjectSearcher(q))foreach(ManagementObject r in search.Get()){var d=new Dictionary<string,object>();foreach(string f in fields)d[f]=r[f];rows.Add(d);}return rows;}
 static object Tool(string name,string arguments,bool hostnameOnly=false){string path=Path.Combine(Root,@"RMS\Tools",name);if(!File.Exists(path))return new{tool=name,present=false};var output=new StringBuilder();var psi=new ProcessStartInfo(path,arguments){WorkingDirectory=Path.GetDirectoryName(path),UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,RedirectStandardInput=true,CreateNoWindow=true};if(hostnameOnly){string scratch=@"C:\Users\Public\Documents\LaunchDeskLab-RmsIdentity-hostname";Directory.CreateDirectory(scratch);File.WriteAllText(Path.Combine(scratch,"echoid.dat"),"0x8\r\n");psi.WorkingDirectory=scratch;}psi.EnvironmentVariables["LSPORT"]="4545";psi.EnvironmentVariables["LSPORT_AVEVA"]="4545";using(var p=new Process()){p.StartInfo=psi;p.OutputDataReceived+=(s,e)=>{if(e.Data!=null)lock(output)output.AppendLine(e.Data);};p.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)lock(output)output.AppendLine(e.Data);};p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();p.StandardInput.Close();bool completed=p.WaitForExit(45000);if(!completed)p.Kill();p.WaitForExit();return new{tool=name,present=true,arguments,completed,exitCode=p.ExitCode,output=output.ToString(),fileSha256=Hash(path),fileVersion=FileVersionInfo.GetVersionInfo(path).FileVersion};}}
 static int Main(string[] args){try{return Execute(args);}catch(Exception e){File.WriteAllText(@"C:\Users\Public\Documents\LaunchDeskLab-rms-restore-identity-error.json",new JavaScriptSerializer().Serialize(new{error=e.ToString()}));return 1;}} static int Execute(string[] args){if(Environment.MachineName!="LD-PROJ-VM"&&Environment.MachineName!="ZHANGSH")throw new Exception("Unexpected VM");string mode=args.Length>0?args[0]:"inventory";object result;
 if(mode=="echoid")result=Tool("echoid.exe","-d");
 else if(mode=="echoid-hostname")result=Tool("echoid.exe","-d",true);else if(mode=="lsmon")result=Tool("lsmon.exe","127.0.0.1");
 else {
 var events=new List<object>();using(var log=new EventLog("Application")){for(int i=log.Entries.Count-1;i>=0&&events.Count<500;i--){var e=log.Entries[i];if(e.TimeGenerated<DateTime.Now.AddDays(-16))break;if(e.Source.IndexOf("Sentinel",StringComparison.OrdinalIgnoreCase)>=0||e.Source.IndexOf("AVEVA",StringComparison.OrdinalIgnoreCase)>=0||e.Source.IndexOf("RMS",StringComparison.OrdinalIgnoreCase)>=0)events.Add(new{source=e.Source,eventId=e.InstanceId,timeUtc=e.TimeGenerated.ToUniversalTime().ToString("o"),type=e.EntryType.ToString(),message=e.Message});}}
 var files=Directory.GetFiles(Root,"*",SearchOption.AllDirectories).Where(p=>!p.Contains(@"\Manuals\")&&!p.Contains(@"\Flex\")).Select(p=>new{path=p,bytes=new FileInfo(p).Length,sha256=Hash(p),version=Path.GetExtension(p).Equals(".exe",StringComparison.OrdinalIgnoreCase)?FileVersionInfo.GetVersionInfo(p).FileVersion:null}).ToArray();
 var textConfigs=new List<object>();foreach(string path in Directory.GetFiles(Root,"*",SearchOption.AllDirectories).Where(p=>Path.GetFileName(p).Equals("echoid.dat",StringComparison.OrdinalIgnoreCase)||Path.GetFileName(p).Equals("AVEVA-Locking.bat",StringComparison.OrdinalIgnoreCase)||Path.GetFileName(p).Equals("ALSConsole.exe.config",StringComparison.OrdinalIgnoreCase)))textConfigs.Add(new{path,content=File.ReadAllText(path)});
 var environment=new Dictionary<string,string>();foreach(string key in new[]{"LSPORT_AVEVA","LSERVRC_AVEVA","LSERVOPTS_AVEVA","LSERVRC","LSERVOPTS","AVEVA_LICENSE_SERVER_LIST"})environment[key]=Environment.GetEnvironmentVariable(key,EnvironmentVariableTarget.Machine);
 result=new{utc=DateTime.UtcNow.ToString("o"),machine=Environment.MachineName,osUtc=DateTime.UtcNow.ToString("o"),computer=Query("SELECT Name,Domain FROM Win32_ComputerSystem",new[]{"Name","Domain"}),bios=Query("SELECT SerialNumber,SMBIOSBIOSVersion FROM Win32_BIOS",new[]{"SerialNumber","SMBIOSBIOSVersion"}),product=Query("SELECT UUID,IdentifyingNumber FROM Win32_ComputerSystemProduct",new[]{"UUID","IdentifyingNumber"}),disks=Query("SELECT Model,SerialNumber,PNPDeviceID FROM Win32_DiskDrive",new[]{"Model","SerialNumber","PNPDeviceID"}),nics=Query("SELECT Name,MACAddress,PNPDeviceID FROM Win32_NetworkAdapter WHERE PhysicalAdapter=True",new[]{"Name","MACAddress","PNPDeviceID"}),volume=Query("SELECT DeviceID,VolumeSerialNumber FROM Win32_LogicalDisk WHERE DeviceID='C:'",new[]{"DeviceID","VolumeSerialNumber"}),services=Query("SELECT Name,State,PathName,StartName,ProcessId FROM Win32_Service WHERE Name='Sentinel RMS License Manager_AVEVA' OR Name='AVEVA RULES Server'",new[]{"Name","State","PathName","StartName","ProcessId"}),files,textConfigs,environment,events};}
 File.WriteAllText(@"C:\Users\Public\Documents\LaunchDeskLab-rms-restore-identity-"+mode+".json",new JavaScriptSerializer{MaxJsonLength=8*1024*1024}.Serialize(result));return 0;}
}
}
